    ,
      cs: ["kominíček"],
      es: ['cuerno de la abundancia'],
      nl: ['Doodstrompet'],
      pt: ['corno-da-abundância', 'orelha-de-morcego', 'viuvinhas'],
      ro: ['trâmbița piticilor'],
